{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — focused coaching for steady, practical wellbeing</title>
  <meta name="description" content="Short, focused work with measurable habit outcomes. VIP days and curated packages to shift daily patterns in {{CITY}}, {{STATE}}." />
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="layout-clinic">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary navigation">
        <a href="/">Home</a>
        <a href="about.html">About</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Programs</a>
        <a href="pricing.html">Rates</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
      <div class="contact-cta">
        <a class="btn primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button class="nav-toggle" aria-label="Toggle menu">☰</button>
      </div>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-content">
          <h1 class="eyebrow">A focused reset for how you live your days</h1>
          <h2 class="title">Small changes. Lasting daily composition.</h2>
          <p class="lede">I help busy people translate what matters into routines and habits that actually fit a real week. Outcomes, simple practices, and precise coaching — in-person and remote across {{CITY}}, {{STATE}}.</p>
          <div class="hero-actions">
            <a class="btn big primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/programs.html">Explore programs</a>
          </div>
          <div class="mood-card" id="mood-card">
            <h3>How do you feel today?</h3>
            <div class="mood-options" role="radiogroup" aria-label="Select mood">
              <button class="mood" data-key="overwhelmed">Overwhelmed</button>
              <button class="mood" data-key="flat">Flat / Low energy</button>
              <button class="mood" data-key="busy">Busy but motivated</button>
              <button class="mood" data-key="curious">Curious to experiment</button>
            </div>
            <div class="method-suggestion">
              <strong class="method-title">A simple reset</strong>
              <p class="method-desc">Choose how to begin — brief practices to anchor your day and a single habit to track for a week.</p>
              <div class="method-cta-wrap">
                <a class="btn method-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
                <span class="method-note">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></span>
              </div>
            </div>
          </div>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <svg viewBox="0 0 600 480" class="hero-svg">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#E6F4F1" />
                <stop offset="1" stop-color="#F7F9FC" />
              </linearGradient>
            </defs>
            <rect width="100%" height="100%" fill="url(#g1)" rx="18"></rect>
            <g transform="translate(40,60)" fill="none" stroke="#A7C9C1" stroke-width="2">
              <path d="M0,300 C80,100 240,100 320,300" stroke-opacity=".15"></path>
              <circle cx="150" cy="180" r="52" fill="#CDEBE3" stroke="none" opacity="0.95"></circle>
              <rect x="230" y="220" width="120" height="80" rx="8" fill="#F6FDFC" stroke-opacity="0.7"></rect>
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- GALLERY (framework snapshots) -->
    <section class="gallery" id="gallery">
      <div class="wrap">
        <h3 class="section-title">Ways we work together</h3>
        <p class="section-lead">Short, precise engagements designed to change how you spend your time and attention.</p>
        <div class="cards">
          <article class="card">
            <h4>VIP Design Day</h4>
            <p>One intensive day to redesign your week, create anchors, and leave with a set of daily habits to trial.</p>
            <div class="card-meta">Includes a follow-up check-in</div>
          </article>

          <article class="card">
            <h4>Eight-Week Habit Clinic</h4>
            <p>Weekly sessions with clear behavior targets, habit templates, and accountability checkpoints.</p>
            <div class="card-meta">Outcome-focused milestones</div>
          </article>

          <article class="card">
            <h4>Weekly Tune-Ups</h4>
            <p>Short 30-minute sessions to adjust and keep momentum for busy spells.</p>
            <div class="card-meta">Flexible scheduling</div>
          </article>
        </div>
      </div>
    </section>

    <!-- WHAT TO EXPECT (includes Pricing Comparator) -->
    <section class="what-to-expect" id="what-to-expect">
      <div class="wrap">
        <h3 class="section-title">What to expect</h3>
        <p class="section-lead">Clear targets, habit scaffolds, and practical measurement — no medical promises, just better daily systems.</p>

        <div class="expect-grid">
          <div class="expect-list">
            <h4>Our commitments</h4>
            <ul>
              <li>Define 1–3 measurable outcomes to track.</li>
              <li>Design short, repeatable practices for the week.</li>
              <li>Provide templates and a short check-in cadence.</li>
            </ul>
          </div>

          <div class="pricing-widget">
            <h4>Rates at a glance</h4>
            <div class="toggle">
              <label class="switch">
                <input id="price-toggle" type="checkbox" aria-label="Toggle price view">
                <span class="slider"></span>
              </label>
              <div class="toggle-labels">
                <span class="label-monthly active">Monthly</span>
                <span class="label-package">Package</span>
              </div>
            </div>

            <div class="prices">
              <div class="price-row">
                <div class="label">VIP Design Day</div>
                <div class="amount" data-month="950" data-package="800">$950</div>
              </div>
              <div class="price-row">
                <div class="label">8-Week Clinic</div>
                <div class="amount" data-month="520" data-package="420">$520</div>
              </div>
              <div class="price-row">
                <div class="label">Weekly Tune-Ups</div>
                <div class="amount" data-month="120" data-package="95">$120</div>
              </div>
            </div>
            <p class="price-note">Toggle to compare per-session monthly rates vs pre-paid package rates.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- OBJECTIONS -->
    <section class="objections" id="objections">
      <div class="wrap">
        <h3 class="section-title">Questions people ask</h3>
        <div class="faq-grid">
          <div class="faq">
            <h4>Will this fit my unpredictable schedule?</h4>
            <p>Yes. Each plan centers on minimal, repeatable actions that flex with your week while preserving measurable progress.</p>
          </div>
          <div class="faq">
            <h4>Is this therapy or medical care?</h4>
            <p>These are coaching frameworks for daily function and habit change. No medical or clinical claims are made.</p>
          </div>
          <div class="faq">
            <h4>How soon will I see change?</h4>
            <p>Expect clearer routines in days and measurable habit shifts over weeks; change depends on consistent practice.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" id="cta">
      <div class="wrap cta-card">
        <div>
          <h3>Ready to reframe your days?</h3>
          <p>Book a short discovery conversation — we’ll map a single trial habit and the simplest supports to hold it.</p>
        </div>
        <div class="cta-actions">
          <a class="btn big primary-cta" id="primary-cta-bottom" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Contact: {{EMAIL}}</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div class="footer-brand">
        <strong>{{BUSINESS_NAME}}</strong>
        <div class="muted">Coaching · Habits · Outcomes</div>
      </div>
      <div class="footer-links">
        <a href="/about.html">About</a>
        <a href="/programs.html">Programs</a>
        <a href="/pricing.html">Rates</a>
        <a href="/contact.html">Connect</a>
      </div>
      <div class="footer-contact">
        <div>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <div>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        <div class="muted">Serving {{CITY}}, {{STATE}}</div>
      </div>
    </div>
  </footer>

</body>
</html>"} 
