{"path":"assets/css/styles.css","content":"/* Core styles - no external fonts */
:root{
  --bg:#fbfdfc;
  --muted:#6b6f72;
  --accent:#2d8f82;
  --accent-2:#6bb7a8;
  --card:#fff;
  --radius:12px;
  --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#0b1a18;background:var(--bg);-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,#ffffffcc,transparent);backdrop-filter:blur(6px);position:sticky;top:0;z-index:40;border-bottom:1px solid #eef3f1}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--accent);text-decoration:none}
.main-nav{margin-left:24px;display:flex;gap:12px}
.main-nav a{color:#13322f;text-decoration:none;padding:6px 8px;border-radius:6px}
.main-nav a:hover{background:#eef7f4}
.contact-cta{margin-left:auto;display:flex;align-items:center;gap:8px}
.btn{display:inline-block;padding:8px 14px;border-radius:10px;text-decoration:none;color:#08201d;background:transparent;border:1px solid transparent}
.btn.ghost{background:transparent;border:1px solid #dfeeea}
.btn.primary-cta{background:var(--accent);color:#fff}
.btn.big{padding:12px 18px;font-weight:600}
.nav-toggle{display:none}

/* HERO */
.hero{background-image:url('../assets/img/pattern.svg');background-repeat:repeat;padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center}
.hero-content .eyebrow{font-size:14px;color:var(--muted);margin:0 0 8px}
.hero-content .title{font-size:28px;margin:0 0 12px}
.lede{color:var(--muted);margin:0 0 18px}
.hero-actions{display:flex;gap:10px;margin-bottom:18px}
.hero-visual{border-radius:16px;overflow:hidden}
.hero-svg{width:100%;height:100%;display:block}

.mood-card{background:var(--card);border-radius:12px;padding:14px;border:1px solid #eef6f3}
.mood-card h3{margin:0 0 8px}
.mood-options{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
.mood{background:#f6f9f8;border:1px solid #e9f3f0;padding:8px 10px;border-radius:8px;cursor:pointer}
.mood.active{background:var(--accent);color:#fff}
.method-suggestion{border-top:1px dashed #e9f3f0;padding-top:10px}
.method-title{display:block;margin:0 0 6px}
.method-desc{margin:0 0 10px;color:var(--muted)}
.method-cta-wrap{display:flex;gap:10px;align-items:center}
.method-note{color:var(--muted);font-size:13px}

/* GALLERY */
.gallery{padding:36px 0}
.section-title{font-size:18px;margin:0 0 6px}
.section-lead{color:var(--muted);margin:0 0 18px}
.cards{display:flex;gap:14px}
.card{background:var(--card);padding:16px;border-radius:12px;border:1px solid #edf6f3;flex:1}
.card h4{margin:0 0 8px}
.card-meta{font-size:13px;color:var(--muted);margin-top:10px}

/* WHAT TO EXPECT */
.what-to-expect{padding:36px 0}
.expect-grid{display:flex;gap:20px}
.expect-list{flex:1}
.pricing-widget{width:320px;background:var(--card);border-radius:12px;padding:12px;border:1px solid #eef6f3}
.toggle{display:flex;align-items:center;gap:12px;margin-bottom:10px}
.switch{position:relative;display:inline-block;width:46px;height:26px}
.switch input{display:none}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#e9f4f1;border-radius:26px}
.slider:before{content:'';position:absolute;height:20px;width:20px;background:white;left:3px;top:3px;border-radius:50%;transition:transform .25s}
.switch input:checked + .slider:before{transform:translateX(20px)}
.toggle-labels{display:flex;gap:8px;font-size:13px;color:var(--muted)}
.toggle-labels .label-monthly.active{color:#13322f;font-weight:600}
.prices{margin-top:6px}
.price-row{display:flex;justify-content:space-between;padding:8px 0;border-top:1px dashed #f0f7f5}
.price-row:first-of-type{border-top:none}
.amount{font-weight:700}
.price-note{color:var(--muted);font-size:13px;margin-top:8px}

/* OBJECTIONS */
.objections{padding:28px 0}
.faq-grid{display:flex;gap:12px}
.faq{background:var(--card);padding:12px;border-radius:10px;border:1px solid #eef6f3}
.faq h4{margin:0 0 6px}

/* CTA */
.cta{padding:36px 0}
.cta-card{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(180deg,#ffffff, #f6fdfb);padding:18px;border-radius:12px;border:1px solid #e8f5ef}

/* FOOTER */
.site-footer{border-top:1px solid #eef3f1;padding:20px 0;margin-top:30px}
.footer-grid{display:flex;justify-content:space-between;gap:20px}
.footer-brand strong{color:#13322f}
.muted{color:var(--muted);font-size:13px}

/* Responsive */
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .main-nav{display:none}
  .nav-toggle{display:inline-block}
  .cards{flex-direction:column}
  .expect-grid{flex-direction:column}
  .faq-grid{flex-direction:column}
  .footer-grid{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"// Interactive widgets: pricing comparator and mood-to-method
document.addEventListener('DOMContentLoaded',function(){
  // Pricing toggle
  const toggle = document.getElementById('price-toggle');
  const labelMonthly = document.querySelector('.label-monthly');
  const labelPackage = document.querySelector('.label-package');
  const amounts = Array.from(document.querySelectorAll('.amount'));

  function animateValue(el, start, end, duration){
    const startTime = performance.now();
    function step(now){
      const t = Math.min(1,(now-startTime)/duration);
      const value = Math.round(start + (end-start)*t);
      el.textContent = '$' + value;
      if(t<1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  function setPrices(usePackage){
    amounts.forEach(a => {
      const month = parseInt(a.getAttribute('data-month'),10) || 0;
      const pack = parseInt(a.getAttribute('data-package'),10) || month;
      const from = parseInt(a.textContent.replace(/[^0-9]/g,'')) || (usePackage?month:pack);
      const to = usePackage?pack:month;
      animateValue(a, from, to, 420);
    });
    if(usePackage){
      labelMonthly.classList.remove('active');
      labelPackage.classList.add('active');
    } else {
      labelMonthly.classList.add('active');
      labelPackage.classList.remove('active');
    }
  }

  if(toggle){
    // initialize based on default checked state
    setPrices(toggle.checked);
    toggle.addEventListener('change',function(e){
      setPrices(e.target.checked);
    });
  }

  // Mood-to-Method selector
  const moodButtons = document.querySelectorAll('.mood');
  const methodTitle = document.querySelector('.method-title');
  const methodDesc = document.querySelector('.method-desc');
  const methodCta = document.querySelector('.method-cta');
  const primaryCtas = document.querySelectorAll('.primary-cta');

  const methods = {
    overwhelmed:{
      title:'Micro-anchors & a single metric',
      desc:'Start with two tiny anchors (2–5 minutes) and one daily metric you can track. Short check-ins keep the plan light and steady.',
      cta:'Book a short reset'
    },
    flat:{
      title:'Energy scaffolds',
      desc:'Brief movement, breath, and a small structure to reclaim baseline energy. We design a predictable mini-routine to repeat daily.',
      cta:'Try an energy tune-up'
    },
    busy:{
      title:'Priority-first planning',
      desc:'We map priorities into time blocks and build a pre-commit template so your best work happens during realistic windows.',
      cta:'Schedule a planning day'
    },
    curious:{
      title:'Experiment & measure',
      desc:'Choose one practice to trial with clear criteria. Weekly reviews refine what to keep and what to drop.',
      cta:'Start an experiment'
    }
  };

  function selectMood(key, btn){
    moodButtons.forEach(b=>b.classList.remove('active'));
    if(btn) btn.classList.add('active');
    const m = methods[key] || methods['curious'];
    methodTitle.textContent = m.title;
    methodDesc.textContent = m.desc;
    methodCta.textContent = m.cta + ' — ' + (document.querySelector('.method-note a')?document.querySelector('.method-note a').textContent:'');
    // Update main CTAs to reflect suggested phrasing
    primaryCtas.forEach(el=>{
      el.textContent = m.cta;
      el.setAttribute('data-suggest',key);
    });
  }

  moodButtons.forEach(b=>{
    b.addEventListener('click',function(){
      selectMood(b.getAttribute('data-key'), b);
    });
  });

  // Default selection
  const defaultBtn = document.querySelector('.mood[data-key="curious"]');
  if(defaultBtn) selectMood('curious', defaultBtn);

  // Small nav toggle for mobile
  const navToggle = document.querySelector('.nav-toggle');
  const nav = document.querySelector('.main-nav');
  if(navToggle){
    navToggle.addEventListener('click', function(){
      if(nav.style.display==='flex') nav.style.display='none'; else nav.style.display='flex';
    });
  }

});"} 
